14.         final ATermAppl literalValue = literal.getTerm();
15.         if (literalValue != null) {
16.             if (datatype != null) {
17.                 if (!literal.hasType(datatype)) {
18.                     try {
19.                         if (!_dtReasoner.isSatisfiable(Collections.singleton(datatype), literal.getValue())) {
20.                             continue;
21.                         }
22.                     } catch (final DatatypeReasonerException e) {
23.                         final String msg = format("Unexpected datatype reasoner exception while fetching property values (%s,%s,%s): %s", s, role, datatype, e.getMessage());
24.                         _logger.severe(msg);
25.                         throw new InternalReasonerException(msg);
26.                     }
27.                 }
28.             }
29.             if (isIndependent && ds.isIndependent()) {
30.                 values.add(literalValue);
31.             } else {
32.                 if (!onlyObvious) {
